      entity_id: value_entity_id,
      pos_x: value_pos_x,
      pos_y: value_pos_y,
      pos_z: value_pos_z,
      yaw: value_yaw,
      pitch: value_pitch,
      vel_x: value_vel_x,
      vel_y: value_vel_y,
      vel_z: value_vel_z,
      health: value_health,
      weapon: value_weapon,
      damage: value_damage,
      moving: value_moving,
      firing: value_firing
