      v_damage = v
      v = rv >>> 46 &&& 0x1
      v_moving = v == 1
      v = rv >>> 47
      v_firing = v == 1

      value = %Bench.MixedEntity{
        entity_id: v_entity_id,
        pos_x: v_pos_x,
        pos_y: v_pos_y,
        pos_z: v_pos_z,
        yaw: v_yaw,
        pitch: v_pitch,
        vel_x: v_vel_x,
        vel_y: v_vel_y,
        vel_z: v_vel_z,
        health: v_health,
        weapon: v_weapon,
