            v = rv >>> 27
            v_hit_crit = v == 1

            v_hit = %Bench.MixedHitEvent{
              target_id: v_hit_target_id,
              damage: v_hit_damage,
              hit_kind: v_hit_hit_kind,
              crit: v_hit_crit
            }

            bits_read = 30
            {bits_read, {:hit, v_hit}}

          2 ->
            if 16 > num_bits, do: throw(:invalid)
            rv = rd(data, 2, 14)
            v = rv &&& 0x3
            v_chat_channel = v
            v = rv >>> 2
            v_chat_speaker = v
            v_chat = %Bench.MixedChatEvent{channel: v_chat_channel, speaker: v_chat_speaker}
            bits_read = 16
            {bits_read, {:chat, v_chat}}

          3 ->
            if 20 > num_bits, do: throw(:invalid)
            rv = rd(data, 2, 18)
            v = rv &&& 0x3FF
            v_pickup_item_id = v
            v = rv >>> 10
            v_pickup_amount = v
            v_pickup = %Bench.MixedPickupEvent{item_id: v_pickup_item_id, amount: v_pickup_amount}
            bits_read = 20
            {bits_read, {:pickup, v_pickup}}

          _ ->
            # None — the tag is the whole wire (SPEC §4.8)
            {bits_read, nil}
        end

      {:ok, v, bits_read}
    catch
      :invalid -> :error
    end
  end

  @doc """
  Decodes a MixedEvent from the first num_bits of data: read_mixed_event_bits/2
  with the count dropped, the family read verdict.
  """
  @spec read_mixed_event(binary(), non_neg_integer()) :: {:ok, Bench.MixedEvent.t()} | :error
  def read_mixed_event(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    case read_mixed_event_bits(data, num_bits) do
      {:ok, value, _bits_read} -> {:ok, value}
      :error -> :error
    end
  end

  @doc """
  The most wire bits a BenchMixed can take: the longest wire path, align padding at its worst case (SPEC §6.1).
  """
  @spec bench_mixed_max_bits() :: pos_integer()
  def bench_mixed_max_bits, do: 3630

  @doc """
  bench_mixed_max_bits/0 in bytes, rounded up to the family 8-byte write-buffer
  granularity.
  """
  @spec bench_mixed_max_bytes() :: pos_integer()
  def bench_mixed_max_bytes, do: 456

  @doc """
  The §5 zero form of BenchMixed: all-zero storage. Specified defaults live
  only in construction (`%Bench.BenchMixed{}`).
  """
  @spec zero_bench_mixed() :: Bench.BenchMixed.t()
  def zero_bench_mixed do
    %Bench.BenchMixed{
      sequence: 0,
      ack_sequence: 0,
      ack_bits: 0,
      session_id: 0,
      client_id: 0,
      nonce: 0,
      world_time: 0,
      frame_tick: 0,
      server_time: 0,
      entities: [],
      stats: [],
      game_event: nil,
      loadout: List.duplicate(0, 4),
      player_name: <<>>,
      payload: <<>>,
      aim_x: 0.0,
      aim_y: 0.0,
      aim_z: 0.0,
      recoil: 0.0,
      drift: 0.0,
      wide_key: 0,
      flux: 0,
      ping: 0,
      crc_hint: 0,
      has_extra: false,
      extra: 0,
      idle_ticks: 0
    }
  end

  @doc """
  Packs a BenchMixed into a fresh binary and returns the wire bytes. The
  writer trusts the caller up to the O(1) contract checks, which raise
  ArgumentError — always on, since the BEAM has no compile-out assert.
  """
  @spec write_bench_mixed!(Bench.BenchMixed.t()) :: binary()
  def write_bench_mixed!(value) do
    %{
      sequence: value_sequence,
      ack_sequence: value_ack_sequence,
      ack_bits: value_ack_bits,
      session_id: value_session_id,
      client_id: value_client_id,
      nonce: value_nonce,
      world_time: value_world_time,
      frame_tick: value_frame_tick,
      server_time: value_server_time,
      entities: value_entities,
      stats: value_stats,
      game_event: value_game_event,
      loadout: value_loadout,
      player_name: value_player_name,
      payload: value_payload,
      aim_x: value_aim_x,
      aim_y: value_aim_y,
      aim_z: value_aim_z,
      recoil: value_recoil,
      drift: value_drift,
      wide_key: value_wide_key,
      flux: value_flux,
      ping: value_ping,
      crc_hint: value_crc_hint,
      has_extra: value_has_extra,
      extra: value_extra,
      idle_ticks: value_idle_ticks
    } = value

    # const(0xC0DE, 16) rides the wire (SPEC §4.3)
    v = 49374
    scratch = v
    v = value_sequence &&& 0xFFFF
    scratch = scratch ||| v <<< 16

    if value_ack_sequence < 0 do
      raise ArgumentError, "value.ack_sequence is below the wire minimum"
    end

    if value_ack_sequence > 65535 do
      raise ArgumentError, "value.ack_sequence is above the wire maximum"
    end

    v = value_ack_sequence
    scratch = scratch ||| v <<< 32
    v = value_ack_bits &&& 0xFFFFFFFF
    sc0 = scratch
    scratch = v
    v = value_session_id &&& 0xFFFFFFFF
    sc1 = scratch
    scratch = v
    v = value_session_id >>> 32 &&& 0xFFFFFFFF
    sc2 = scratch
    scratch = v
    v = value_client_id &&& 0xFFFFFFFF
    sc3 = scratch
    scratch = v

    if value_nonce < 0 do
      raise ArgumentError, "value.nonce is below the wire minimum"
    end

    if value_nonce > 18_446_744_073_709_551_615 do
      raise ArgumentError, "value.nonce is above the wire maximum"
    end

    v = value_nonce &&& 0xFFFFFFFF
    sc4 = scratch
    scratch = v
    v = value_nonce >>> 32
    sc5 = scratch
    scratch = v

    if value_world_time < -1_000_000_000_000 do
      raise ArgumentError, "value.world_time is below the wire minimum"
    end

    if value_world_time > 1_000_000_000_000 do
      raise ArgumentError, "value.world_time is above the wire maximum"
    end

    w = value_world_time + 1_000_000_000_000
    v = w &&& 0xFFFFFFFF
    sc6 = scratch
    scratch = v
    v = w >>> 32
    scratch = scratch ||| v <<< 32
    v = value_frame_tick &&& 0xFFFFFFFF
    sc7 = scratch
    scratch = scratch >>> 40
    scratch = scratch ||| v <<< 1
    v = value_frame_tick >>> 32 &&& 0xFFFF
    scratch = scratch ||| v <<< 33

    if value_server_time < 0 do
      raise ArgumentError, "value.server_time is below the wire minimum"
    end

    if value_server_time > 16_776_960 do
      raise ArgumentError, "value.server_time is above the wire maximum"
    end

    v = value_server_time
    sc8 = scratch
    scratch = scratch >>> 48
    scratch = scratch ||| v <<< 1
    n = length(value_entities)

    if n < 1 do
      raise ArgumentError, "value.entities count is below the wire minimum"
    end

    if n > 8 do
      raise ArgumentError, "value.entities count is above the wire maximum"
    end

    v = n - 1
    scratch = scratch ||| v <<< 25

    data =
      <<sc0::little-size(6)-unit(8), sc1::little-size(4)-unit(8), sc2::little-size(4)-unit(8),
        sc3::little-size(4)-unit(8), sc4::little-size(4)-unit(8), sc5::little-size(4)-unit(8),
        sc6::little-size(4)-unit(8), sc7::little-size(5)-unit(8), sc8::little-size(6)-unit(8),
        scratch::little-size(3)-unit(8)>>

    scratch = scratch >>> 24
    scratch_bits = 4

    {data, scratch, scratch_bits} =
      w_bench_mixed_entities(value_entities, data, scratch, scratch_bits)

    n = length(value_stats)

    if n > 80 do
      raise ArgumentError, "value.stats count is above the wire maximum"
    end

    v = n
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 7
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    {data, scratch, scratch_bits} = w_bench_mixed_stats(value_stats, data, scratch, scratch_bits)

    v =
      case value_game_event do
        nil ->
          0

        {:hit, _} ->
          1

        {:chat, _} ->
          2

        {:pickup, _} ->
          3

        value_game_event_other ->
          raise ArgumentError,
                "value.game_event is not a MixedEvent value: #{inspect(value_game_event_other)}"
      end

    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 2
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7

    {data, scratch, scratch_bits} =
      case value_game_event do
        {:hit, value_game_event_hit} ->
          %{
            target_id: value_game_event_hit_target_id,
            damage: value_game_event_hit_damage,
            hit_kind: value_game_event_hit_hit_kind,
            crit: value_game_event_hit_crit
          } = value_game_event_hit

          v = value_game_event_hit_target_id &&& 0xFFF
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 12

          if value_game_event_hit_damage < 0 do
            raise ArgumentError, "value.game_event.hit.damage is below the wire minimum"
          end

          if value_game_event_hit_damage > 4095 do
            raise ArgumentError, "value.game_event.hit.damage is above the wire maximum"
          end

          v = value_game_event_hit_damage
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 12

          if value_game_event_hit_hit_kind < 0 do
            raise ArgumentError, "value.game_event.hit.hit_kind is below the wire minimum"
          end

          if value_game_event_hit_hit_kind > 7 do
            raise ArgumentError, "value.game_event.hit.hit_kind is above the wire maximum"
          end

          v = value_game_event_hit_hit_kind
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 3
          v = if value_game_event_hit_crit, do: 1, else: 0
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 1
          flush = scratch_bits >>> 3
          data = <<data::binary, scratch::little-size(flush)-unit(8)>>
          scratch = scratch >>> (flush <<< 3)
          scratch_bits = scratch_bits &&& 7
          {data, scratch, scratch_bits}

        {:chat, value_game_event_chat} ->
          %{
            channel: value_game_event_chat_channel,
            speaker: value_game_event_chat_speaker
          } = value_game_event_chat

          if value_game_event_chat_channel < 0 do
            raise ArgumentError, "value.game_event.chat.channel is below the wire minimum"
          end

          if value_game_event_chat_channel > 3 do
            raise ArgumentError, "value.game_event.chat.channel is above the wire maximum"
          end

          v = value_game_event_chat_channel
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 2
          v = value_game_event_chat_speaker &&& 0xFFF
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 12
          flush = scratch_bits >>> 3
          data = <<data::binary, scratch::little-size(flush)-unit(8)>>
          scratch = scratch >>> (flush <<< 3)
          scratch_bits = scratch_bits &&& 7
          {data, scratch, scratch_bits}

        {:pickup, value_game_event_pickup} ->
          %{
            item_id: value_game_event_pickup_item_id,
            amount: value_game_event_pickup_amount
          } = value_game_event_pickup

          v = value_game_event_pickup_item_id &&& 0x3FF
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 10

          if value_game_event_pickup_amount < 0 do
            raise ArgumentError, "value.game_event.pickup.amount is below the wire minimum"
          end

          if value_game_event_pickup_amount > 255 do
            raise ArgumentError, "value.game_event.pickup.amount is above the wire maximum"
          end

          v = value_game_event_pickup_amount
          scratch = scratch ||| v <<< scratch_bits
          scratch_bits = scratch_bits + 8
          flush = scratch_bits >>> 3
          data = <<data::binary, scratch::little-size(flush)-unit(8)>>
          scratch = scratch >>> (flush <<< 3)
          scratch_bits = scratch_bits &&& 7
          {data, scratch, scratch_bits}

        _ ->
          # None, or an arm whose tag is its whole wire (SPEC §4.8)
          {data, scratch, scratch_bits}
      end

    if length(value_loadout) != 4 do
      raise ArgumentError, "value.loadout must hold exactly 4 elements"
    end

    {data, scratch, scratch_bits} =
      w_bench_mixed_loadout(value_loadout, data, scratch, scratch_bits)

    if byte_size(value_player_name) > 15 do
      raise ArgumentError, "value.player_name longer than the declared 15-byte bound"
    end

    v = byte_size(value_player_name)
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 4
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    # align: zero-pad to the byte boundary (SPEC §4.3)
    data = if scratch_bits != 0, do: <<data::binary, scratch>>, else: data
    # the used bytes ride whole — the stream is byte-aligned here
    data = <<data::binary, value_player_name::binary>>

    if byte_size(value_payload) > 16 do
      raise ArgumentError, "value.payload longer than the declared 16-byte bound"
    end

    v = byte_size(value_payload)
    scratch = v
    # align: zero-pad to the byte boundary (SPEC §4.3)
    data = <<data::binary, scratch>>
    # the used bytes ride whole — the stream is byte-aligned here
    data = <<data::binary, value_payload::binary>>
    v = cf_quantize(value_aim_x, -1.0, 2.0, 200, 200.0)
    scratch = v
    v = cf_quantize(value_aim_y, -1.0, 2.0, 200, 200.0)
    scratch = scratch ||| v <<< 8
    v = cf_quantize(value_aim_z, -1.0, 2.0, 200, 200.0)
    scratch = scratch ||| v <<< 16
    v = f32_bits(value_recoil)
    sc9 = scratch
    scratch = v
    data = <<data::binary, sc9::little-size(3)-unit(8), scratch::little-size(4)-unit(8)>>
    data = put_f64(data, value_drift)
    v = value_wide_key &&& 0xFFFFFFFF
    scratch = v
    v = value_wide_key >>> 32 &&& 0xFFFFFFFF
    sc10 = scratch
    scratch = v
    v = value_wide_key >>> 64 &&& 0xFFFFFFFF
    sc11 = scratch
    scratch = v
    v = value_wide_key >>> 96 &&& 0xFFFFFFFF
    sc12 = scratch
    scratch = v

    if value_flux < -1_267_650_600_228_229_401_496_703_205_376 do
      raise ArgumentError, "value.flux is below the wire minimum"
    end

    if value_flux > 1_267_650_600_228_229_401_496_703_205_376 do
      raise ArgumentError, "value.flux is above the wire maximum"
    end

    w = value_flux + 1_267_650_600_228_229_401_496_703_205_376
    v = w &&& 0xFFFFFFFF
    sc13 = scratch
    scratch = v
    v = w >>> 32 &&& 0xFFFFFFFF
    sc14 = scratch
    scratch = v
    v = w >>> 64 &&& 0xFFFFFFFF
    sc15 = scratch
    scratch = v
    v = w >>> 96
    scratch = scratch ||| v <<< 32

    if value_ping < 0 do
      raise ArgumentError, "value.ping is below the wire minimum"
    end

    if value_ping > 64000 do
      raise ArgumentError, "value.ping is above the wire maximum"
    end

    v = value_ping
    sc16 = scratch
    scratch = scratch >>> 32
    scratch = scratch ||| v <<< 6
    # reserved bits ride as zeros (SPEC §4.3)
    v = 0
    scratch = scratch ||| v <<< 22

    data =
      <<data::binary, sc10::little-size(4)-unit(8), sc11::little-size(4)-unit(8),
        sc12::little-size(4)-unit(8), sc13::little-size(4)-unit(8), sc14::little-size(4)-unit(8),
        sc15::little-size(4)-unit(8), sc16::little-size(4)-unit(8),
        scratch::little-size(3)-unit(8)>>

    scratch = scratch >>> 24
    # align: zero-pad to the byte boundary (SPEC §4.3)
    data = <<data::binary, scratch>>
    v = value_crc_hint &&& 0xFFFFFF
    scratch = v
    v = if value_has_extra, do: 1, else: 0
    scratch = scratch ||| v <<< 24

    if value_extra < 0 do
      raise ArgumentError, "value.extra is below the wire minimum"
    end

    if value_extra > 255 do
      raise ArgumentError, "value.extra is above the wire maximum"
    end

    v = value_extra
    scratch = scratch ||| v <<< 25

    if value_idle_ticks < 0 do
      raise ArgumentError, "value.idle_ticks is below the wire minimum"
    end

    if value_idle_ticks > 15 do
      raise ArgumentError, "value.idle_ticks is above the wire maximum"
    end

    v = value_idle_ticks
    scratch = scratch ||| v <<< 33
    data = <<data::binary, scratch::little-size(4)-unit(8)>>
    scratch = scratch >>> 32
    # the residual byte, statically known to be there
    <<data::binary, scratch>>
  end

  @doc """
  write_bench_mixed!/1 as a verdict: `{:ok, binary}`, or `{:error, message}`
  where the bang form raises ArgumentError.
  """
  @spec write_bench_mixed(Bench.BenchMixed.t()) :: {:ok, binary()} | {:error, String.t()}
  def write_bench_mixed(value) do
    {:ok, write_bench_mixed!(value)}
  rescue
    e in ArgumentError -> {:error, Exception.message(e)}
  end

  @doc """
  Decodes a BenchMixed from the first num_bits of data and REPORTS THE BITS
  CONSUMED (SPEC §5): `{:ok, value, bits_read}`. The count is what frames a
  second object behind the first in one buffer. `:error` rejects the wire
  (bounds, ranges, wire constants, padding); hostile bytes never raise. No
  slack past the payload is required.
  """
  @spec read_bench_mixed_bits(binary(), non_neg_integer()) ::
          {:ok, Bench.BenchMixed.t(), non_neg_integer()} | :error
  def read_bench_mixed_bits(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      if 353 > num_bits, do: throw(:invalid)
      rv = rdw(data, 0, 49)
      v = rv &&& 0xFFFF
      # a read rejects any other value (SPEC §4.3)
      if v != 49374, do: throw(:invalid)
      v = rv >>> 16 &&& 0xFFFF
      v_sequence = v
      v = rv >>> 32 &&& 0xFFFF
      v_ack_sequence = v
      rv = rdw(data, 48, 49)
      v = rv &&& 0xFFFFFFFF
      v_ack_bits = v
      rv = rdw(data, 80, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 112, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_session_id = w
      rv = rdw(data, 144, 49)
      v = rv &&& 0xFFFFFFFF
      v_client_id = v
      rv = rdw(data, 176, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 208, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_nonce = w
      rv = rdw(data, 240, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      v = rv >>> 32 &&& 0x1FF
      w = w ||| v <<< 32
      # a smuggled offset is refused
      if w > 2_000_000_000_000, do: throw(:invalid)
      v_world_time = w - 1_000_000_000_000
      rv = rdw(data, 281, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      v = rv >>> 32 &&& 0xFFFF
      w = w ||| v <<< 32
      v_frame_tick = w
      rv = rd(data, 329, 24)
      v = rv
      # a smuggled offset is refused
      if v > 16_776_960, do: throw(:invalid)
      v_server_time = v
      if 356 > num_bits, do: throw(:invalid)
      rv = rdw(data, 353, 49)
      v = rv &&& 0x7
      n = v + 1
      if 356 + n * 135 > num_bits, do: throw(:invalid)
      {bits_read, v_entities} = r_bench_mixed_entities(n, [], data, num_bits, 356)
      if bits_read + 7 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0x7F
      # the count guards the loop — reject, never clamp
      if v > 80, do: throw(:invalid)
      n = v
      if bits_read + 7 + n * 18 > num_bits, do: throw(:invalid)
      {bits_read, v_stats} = r_bench_mixed_stats_align(n, [], data, num_bits, bits_read + 7)
      if bits_read + 2 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0x3
      bits_read = bits_read + 2

      {bits_read, v_game_event} =
        case v do
          1 ->
            if bits_read + 28 > num_bits, do: throw(:invalid)
            rv = rd(data, bits_read, 28)
            v = rv &&& 0xFFF
            v_game_event_hit_target_id = v
            v = rv >>> 12 &&& 0xFFF
            v_game_event_hit_damage = v
            v = rv >>> 24 &&& 0x7
            v_game_event_hit_hit_kind = v
            v = rv >>> 27
            v_game_event_hit_crit = v == 1

            v_game_event_hit = %Bench.MixedHitEvent{
              target_id: v_game_event_hit_target_id,
              damage: v_game_event_hit_damage,
              hit_kind: v_game_event_hit_hit_kind,
              crit: v_game_event_hit_crit
            }

            bits_read = bits_read + 28
            {bits_read, {:hit, v_game_event_hit}}

          2 ->
            if bits_read + 14 > num_bits, do: throw(:invalid)
            rv = rd(data, bits_read, 14)
            v = rv &&& 0x3
            v_game_event_chat_channel = v
            v = rv >>> 2
            v_game_event_chat_speaker = v

            v_game_event_chat = %Bench.MixedChatEvent{
              channel: v_game_event_chat_channel,
              speaker: v_game_event_chat_speaker
            }

            bits_read = bits_read + 14
            {bits_read, {:chat, v_game_event_chat}}

          3 ->
            if bits_read + 18 > num_bits, do: throw(:invalid)
            rv = rd(data, bits_read, 18)
            v = rv &&& 0x3FF
            v_game_event_pickup_item_id = v
            v = rv >>> 10
            v_game_event_pickup_amount = v

            v_game_event_pickup = %Bench.MixedPickupEvent{
              item_id: v_game_event_pickup_item_id,
              amount: v_game_event_pickup_amount
            }

            bits_read = bits_read + 18
            {bits_read, {:pickup, v_game_event_pickup}}

          _ ->
            # None — the tag is the whole wire (SPEC §4.8)
            {bits_read, nil}
        end

      if bits_read + 32 > num_bits, do: throw(:invalid)
      {bits_read, v_loadout} = r_bench_mixed_loadout_align(4, [], data, num_bits, bits_read)
      if bits_read + 4 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0xF
      len = v
      bits_read = bits_read + 4
      pad = 8 - (bits_read &&& 7) &&& 7

      if pad != 0 do
        if bits_read + pad > num_bits do
          throw(:invalid)
        end

        if rd(data, bits_read, pad) != 0 do
          # nonzero padding is refused (SPEC §4.3)
          throw(:invalid)
        end
      end

      bits_read = bits_read + pad
      if bits_read + len * 8 > num_bits, do: throw(:invalid)
      v_player_name = binary_part(data, bits_read >>> 3, len)
      bits_read = bits_read + len * 8
      # malformed UTF-8 is content the read refuses (SPEC §4.7)
      if not String.valid?(v_player_name), do: throw(:invalid)
      # an interior null is content the read refuses (SPEC §4.7)
      if :binary.match(v_player_name, <<0>>) != :nomatch, do: throw(:invalid)
      if bits_read + 5 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0x1F
      # the length guards the slice — reject, never clamp
      if v > 16, do: throw(:invalid)
      len = v
      bits_read = bits_read + 5
      pad = 8 - (bits_read &&& 7) &&& 7

      if pad != 0 do
        if bits_read + pad > num_bits do
          throw(:invalid)
        end

        if rd(data, bits_read, pad) != 0 do
          # nonzero padding is refused (SPEC §4.3)
          throw(:invalid)
        end
      end

      bits_read = bits_read + pad
      if bits_read + len * 8 > num_bits, do: throw(:invalid)
      v_payload = binary_part(data, bits_read >>> 3, len)
      bits_read = bits_read + len * 8
      if bits_read + 370 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0xFF
      # headroom above the quantum count is refused
      if v > 200, do: throw(:invalid)
      v_aim_x = elem(@cf_tab_0, v)
      v = rv >>> 8 &&& 0xFF
      # headroom above the quantum count is refused
      if v > 200, do: throw(:invalid)
      v_aim_y = elem(@cf_tab_0, v)
      v = rv >>> 16 &&& 0xFF
      # headroom above the quantum count is refused
      if v > 200, do: throw(:invalid)
      v_aim_z = elem(@cf_tab_0, v)
      rv = rdw(data, bits_read + 24, 49)
      v = rv &&& 0xFFFFFFFF
      v_recoil = f32_value(v)
      v_drift = get_f64(data, bits_read + 56)
      rv = rdw(data, bits_read + 120, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, bits_read + 152, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      rv = rdw(data, bits_read + 184, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 64
      rv = rdw(data, bits_read + 216, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 96
      v_wide_key = w
      rv = rdw(data, bits_read + 248, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, bits_read + 280, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      rv = rdw(data, bits_read + 312, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 64
      v = rv >>> 32 &&& 0x3F
      w = w ||| v <<< 96
      # a smuggled offset is refused
      if w > 2_535_301_200_456_458_802_993_406_410_752, do: throw(:invalid)
      v_flux = w - 1_267_650_600_228_229_401_496_703_205_376
      rv = rdw(data, bits_read + 350, 49)
      v = rv &&& 0xFFFF
      # a smuggled offset is refused
      if v > 64000, do: throw(:invalid)
      v_ping = v
      v = rv >>> 16 &&& 0xF
      # reserved bits must read zero (SPEC §4.3)
      if v != 0, do: throw(:invalid)
      bits_read = bits_read + 370
      pad = 8 - (bits_read &&& 7) &&& 7

      if pad != 0 do
        if bits_read + pad > num_bits do
          throw(:invalid)
        end

        if rd(data, bits_read, pad) != 0 do
          # nonzero padding is refused (SPEC §4.3)
          throw(:invalid)
        end
      end

      bits_read = bits_read + pad
      if bits_read + 37 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 37)
      v = rv &&& 0xFFFFFF
      v_crc_hint = v
      v = rv >>> 24 &&& 0x1
      v_has_extra = v == 1
      v = rv >>> 25 &&& 0xFF
      v_extra = v
      v = rv >>> 33
      v_idle_ticks = v

      value = %Bench.BenchMixed{
        sequence: v_sequence,
        ack_sequence: v_ack_sequence,
        ack_bits: v_ack_bits,
        session_id: v_session_id,
        client_id: v_client_id,
        nonce: v_nonce,
        world_time: v_world_time,
        frame_tick: v_frame_tick,
        server_time: v_server_time,
        entities: v_entities,
        stats: v_stats,
        game_event: v_game_event,
        loadout: v_loadout,
        player_name: v_player_name,
        payload: v_payload,
        aim_x: v_aim_x,
        aim_y: v_aim_y,
        aim_z: v_aim_z,
        recoil: v_recoil,
        drift: v_drift,
        wide_key: v_wide_key,
        flux: v_flux,
        ping: v_ping,
        crc_hint: v_crc_hint,
        has_extra: v_has_extra,
        extra: v_extra,
        idle_ticks: v_idle_ticks
      }

      {:ok, value, bits_read + 37}
    catch
      :invalid -> :error
    end
  end

  @doc """
  Decodes a BenchMixed from the first num_bits of data: read_bench_mixed_bits/2
  with the count dropped, the family read verdict.
  """
  @spec read_bench_mixed(binary(), non_neg_integer()) :: {:ok, Bench.BenchMixed.t()} | :error
  def read_bench_mixed(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    case read_bench_mixed_bits(data, num_bits) do
      {:ok, value, _bits_read} -> {:ok, value}
      :error -> :error
    end
  end

  defp w_bench_packet_blob([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_bench_packet_blob([e1, e2, e3, e4 | rest], data, scratch, scratch_bits) do
    v = e1 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    v = e2 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    v = e3 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    v = e4 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_packet_blob(rest, data, scratch, scratch_bits)
  end

  defp w_bench_packet_blob([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_packet_blob(rest, data, scratch, scratch_bits)
  end

  defp r_bench_packet_blob(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_bench_packet_blob(remaining, acc, data, num_bits, bits_read)
       when remaining >= 4 do
    rv = rd(data, bits_read, 32)
    v = rv &&& 0xFF
    e1 = v
    v = rv >>> 8 &&& 0xFF
    e2 = v
    v = rv >>> 16 &&& 0xFF
    e3 = v
    v = rv >>> 24
    e4 = v
    r_bench_packet_blob(remaining - 4, [e4, e3, e2, e1 | acc], data, num_bits, bits_read + 32)
  end

  defp r_bench_packet_blob(remaining, acc, data, num_bits, bits_read) do
    rv = rd(data, bits_read, 8)
    v = rv
    e = v
    r_bench_packet_blob(remaining - 1, [e | acc], data, num_bits, bits_read + 8)
  end

  defp r_bench_packet_blob_align(remaining, acc, data, num_bits, bits_read)
       when remaining >= 9 do
    i = bits_read >>> 3
    q = bits_read &&& 7

    if q == 0 do
      case data do
        <<_::binary-size(^i), rest::binary>> ->
          r_bench_packet_blob_fast(remaining, acc, data, num_bits, bits_read, rest, 0, 0)

        _ ->
          r_bench_packet_blob(remaining, acc, data, num_bits, bits_read)
      end
    else
      case data do
        <<_::binary-size(^i), b0, rest::binary>> ->
          r_bench_packet_blob_fast(
            remaining,
            acc,
            data,
            num_bits,
            bits_read,
            rest,
            b0 >>> q,
            8 - q
          )

        _ ->
          r_bench_packet_blob(remaining, acc, data, num_bits, bits_read)
      end
    end
  end

  defp r_bench_packet_blob_align(remaining, acc, data, num_bits, bits_read),
    do: r_bench_packet_blob(remaining, acc, data, num_bits, bits_read)

  defp r_bench_packet_blob_fast(
         remaining,
         acc,
         data,
         num_bits,
         bits_read,
         <<s1::little-40, s2::little-32, rest::binary>>,
         carry,
         c
       )
       when remaining >= 9 do
    z1 = carry ||| s1 <<< c
    v = z1 &&& 0xFF
    e1 = v
    v = z1 >>> 8 &&& 0xFF
    e2 = v
    v = z1 >>> 16 &&& 0xFF
    e3 = v
    v = z1 >>> 24 &&& 0xFF
    e4 = v
    v = z1 >>> 32 &&& 0xFF
    e5 = v
    z2 = z1 >>> 40 ||| s2 <<< (c + 0)
    v = z2 &&& 0xFF
    e6 = v
    v = z2 >>> 8 &&& 0xFF
    e7 = v
    v = z2 >>> 16 &&& 0xFF
    e8 = v
    v = z2 >>> 24 &&& 0xFF
    e9 = v

    {bits_read, tail} =
      r_bench_packet_blob_fast(
        remaining - 9,
        acc,
        data,
        num_bits,
        bits_read + 72,
        rest,
        z2 >>> 32,
        c
      )

    {bits_read, [e1, e2, e3, e4, e5, e6, e7, e8, e9 | tail]}
  end

  defp r_bench_packet_blob_fast(remaining, acc, data, num_bits, bits_read, _rest, _carry, _c),
    do: r_bench_packet_blob(remaining, acc, data, num_bits, bits_read)

  defp w_bench_mixed_entities([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_bench_mixed_entities([e | rest], data, scratch, scratch_bits) do
    %{
      entity_id: e_entity_id,
      pos_x: e_pos_x,
      pos_y: e_pos_y,
      pos_z: e_pos_z,
      yaw: e_yaw,
      pitch: e_pitch,
      vel_x: e_vel_x,
      vel_y: e_vel_y,
      vel_z: e_vel_z,
      health: e_health,
      weapon: e_weapon,
      damage: e_damage,
      moving: e_moving,
      firing: e_firing
    } = e

    v = e_entity_id &&& 0xFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 12

    if e_pos_x < -16383 do
      raise ArgumentError, "e.pos_x is below the wire minimum"
    end

    if e_pos_x > 16383 do
      raise ArgumentError, "e.pos_x is above the wire maximum"
    end

    v = e_pos_x + 16383
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 15

    if e_pos_y < -16383 do
      raise ArgumentError, "e.pos_y is below the wire minimum"
    end

    if e_pos_y > 16383 do
      raise ArgumentError, "e.pos_y is above the wire maximum"
    end

    v = e_pos_y + 16383
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 15

    if e_pos_z < -16383 do
      raise ArgumentError, "e.pos_z is below the wire minimum"
    end

    if e_pos_z > 16383 do
      raise ArgumentError, "e.pos_z is above the wire maximum"
    end

    v = e_pos_z + 16383
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 15
    v = e_yaw &&& 0x1FF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 9
    v = e_pitch &&& 0x1FF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 9

    if e_vel_x < -2048 do
      raise ArgumentError, "e.vel_x is below the wire minimum"
    end

    if e_vel_x > 2047 do
      raise ArgumentError, "e.vel_x is above the wire maximum"
    end

    v = e_vel_x + 2048
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 12

    if e_vel_y < -2048 do
      raise ArgumentError, "e.vel_y is below the wire minimum"
    end

    if e_vel_y > 2047 do
      raise ArgumentError, "e.vel_y is above the wire maximum"
    end

    v = e_vel_y + 2048
    sc1 = scratch
    fl1 = scratch_bits >>> 3
    scratch = scratch >>> (fl1 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 12

    if e_vel_z < -2048 do
      raise ArgumentError, "e.vel_z is below the wire minimum"
    end

    if e_vel_z > 2047 do
      raise ArgumentError, "e.vel_z is above the wire maximum"
    end

    v = e_vel_z + 2048
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 12

    if e_health < 0 do
      raise ArgumentError, "e.health is below the wire minimum"
    end

    if e_health > 1000 do
      raise ArgumentError, "e.health is above the wire maximum"
    end

    v = e_health
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 10
    v = Bench.MixedWeapon.to_int(e_weapon)
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 4

    if e_damage >>> 8 != 0 do
      raise ArgumentError, "e.damage holds a mask bit above the 8-bit wire"
    end

    v = e_damage
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    v = if e_moving, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    v = if e_firing, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    flush = scratch_bits >>> 3

    data =
      <<data::binary, sc0::little-size(fl0)-unit(8), sc1::little-size(fl1)-unit(8),
        scratch::little-size(flush)-unit(8)>>

    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_mixed_entities(rest, data, scratch, scratch_bits)
  end

  defp w_bench_mixed_stats([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_bench_mixed_stats([e1, e2, e3, e4 | rest], data, scratch, scratch_bits) do
    %{stat_id: e1_stat_id, delta: e1_delta} = e1
    v = e1_stat_id &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8

    if e1_delta < -512 do
      raise ArgumentError, "e.delta is below the wire minimum"
    end

    if e1_delta > 511 do
      raise ArgumentError, "e.delta is above the wire maximum"
    end

    v = e1_delta + 512
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 10
    %{stat_id: e2_stat_id, delta: e2_delta} = e2
    v = e2_stat_id &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8

    if e2_delta < -512 do
      raise ArgumentError, "e.delta is below the wire minimum"
    end

    if e2_delta > 511 do
      raise ArgumentError, "e.delta is above the wire maximum"
    end

    v = e2_delta + 512
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 10
    %{stat_id: e3_stat_id, delta: e3_delta} = e3
    v = e3_stat_id &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8

    if e3_delta < -512 do
      raise ArgumentError, "e.delta is below the wire minimum"
    end

    if e3_delta > 511 do
      raise ArgumentError, "e.delta is above the wire maximum"
    end

    v = e3_delta + 512
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 10
    %{stat_id: e4_stat_id, delta: e4_delta} = e4
    v = e4_stat_id &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8

    if e4_delta < -512 do
      raise ArgumentError, "e.delta is below the wire minimum"
    end

    if e4_delta > 511 do
      raise ArgumentError, "e.delta is above the wire maximum"
    end

    v = e4_delta + 512
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 10
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_mixed_stats(rest, data, scratch, scratch_bits)
  end

  defp w_bench_mixed_stats([e | rest], data, scratch, scratch_bits) do
    %{stat_id: e_stat_id, delta: e_delta} = e
    v = e_stat_id &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8

    if e_delta < -512 do
      raise ArgumentError, "e.delta is below the wire minimum"
    end

    if e_delta > 511 do
      raise ArgumentError, "e.delta is above the wire maximum"
    end

    v = e_delta + 512
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 10
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_mixed_stats(rest, data, scratch, scratch_bits)
  end

  defp w_bench_mixed_loadout([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_bench_mixed_loadout([e1, e2, e3, e4 | rest], data, scratch, scratch_bits) do
    v = e1 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    v = e2 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    v = e3 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    v = e4 &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_mixed_loadout(rest, data, scratch, scratch_bits)
  end

  defp w_bench_mixed_loadout([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_mixed_loadout(rest, data, scratch, scratch_bits)
  end

  defp r_bench_mixed_entities(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_bench_mixed_entities(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFF
    e_entity_id = v
    v = rv >>> 12 &&& 0x7FFF
    # a smuggled offset is refused
    if v > 32766, do: throw(:invalid)
    e_pos_x = v - 16383
    v = rv >>> 27 &&& 0x7FFF
    # a smuggled offset is refused
    if v > 32766, do: throw(:invalid)
    e_pos_y = v - 16383
    rv = rdw(data, bits_read + 42, 49)
    v = rv &&& 0x7FFF
    # a smuggled offset is refused
    if v > 32766, do: throw(:invalid)
    e_pos_z = v - 16383
    v = rv >>> 15 &&& 0x1FF
    e_yaw = v
    v = rv >>> 24 &&& 0x1FF
    e_pitch = v
    v = rv >>> 33 &&& 0xFFF
    e_vel_x = v - 2048
    rv = rdw(data, bits_read + 87, 48)
    v = rv &&& 0xFFF
    e_vel_y = v - 2048
    v = rv >>> 12 &&& 0xFFF
    e_vel_z = v - 2048
    v = rv >>> 24 &&& 0x3FF
    # a smuggled offset is refused
    if v > 1000, do: throw(:invalid)
    e_health = v
    v = rv >>> 34 &&& 0xF
    {:ok, e_weapon} = Bench.MixedWeapon.from_int(v)
    v = rv >>> 38 &&& 0xFF
    e_damage = v
    v = rv >>> 46 &&& 0x1
    e_moving = v == 1
    v = rv >>> 47
    e_firing = v == 1

    e = %Bench.MixedEntity{
      entity_id: e_entity_id,
      pos_x: e_pos_x,
      pos_y: e_pos_y,
      pos_z: e_pos_z,
      yaw: e_yaw,
      pitch: e_pitch,
      vel_x: e_vel_x,
      vel_y: e_vel_y,
      vel_z: e_vel_z,
      health: e_health,
      weapon: e_weapon,
      damage: e_damage,
      moving: e_moving,
      firing: e_firing
    }

    r_bench_mixed_entities(remaining - 1, [e | acc], data, num_bits, bits_read + 135)
  end

  defp r_bench_mixed_stats(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_bench_mixed_stats(remaining, acc, data, num_bits, bits_read)
       when remaining >= 2 do
    rv = rdw(data, bits_read, 36)
    v = rv &&& 0xFF
    e1_stat_id = v
    v = rv >>> 8 &&& 0x3FF
    e1_delta = v - 512
    e1 = %Bench.MixedStat{stat_id: e1_stat_id, delta: e1_delta}
    v = rv >>> 18 &&& 0xFF
    e2_stat_id = v
    v = rv >>> 26
    e2_delta = v - 512
    e2 = %Bench.MixedStat{stat_id: e2_stat_id, delta: e2_delta}
    r_bench_mixed_stats(remaining - 2, [e2, e1 | acc], data, num_bits, bits_read + 36)
  end

  defp r_bench_mixed_stats(remaining, acc, data, num_bits, bits_read) do
    rv = rd(data, bits_read, 18)
    v = rv &&& 0xFF
    e_stat_id = v
    v = rv >>> 8
    e_delta = v - 512
    e = %Bench.MixedStat{stat_id: e_stat_id, delta: e_delta}
    r_bench_mixed_stats(remaining - 1, [e | acc], data, num_bits, bits_read + 18)
  end

  defp r_bench_mixed_stats_align(remaining, acc, data, num_bits, bits_read)
       when remaining >= 4 do
    i = bits_read >>> 3
    q = bits_read &&& 7

    if q == 0 do
      case data do
        <<_::binary-size(^i), rest::binary>> ->
          r_bench_mixed_stats_fast(remaining, acc, data, num_bits, bits_read, rest, 0, 0)

        _ ->
          r_bench_mixed_stats(remaining, acc, data, num_bits, bits_read)
      end
    else
      case data do
        <<_::binary-size(^i), b0, rest::binary>> ->
          r_bench_mixed_stats_fast(
            remaining,
            acc,
            data,
            num_bits,
            bits_read,
            rest,
            b0 >>> q,
            8 - q
          )

        _ ->
          r_bench_mixed_stats(remaining, acc, data, num_bits, bits_read)
      end
    end
  end

  defp r_bench_mixed_stats_align(remaining, acc, data, num_bits, bits_read),
    do: r_bench_mixed_stats(remaining, acc, data, num_bits, bits_read)

  defp r_bench_mixed_stats_fast(
         remaining,
         acc,
         data,
         num_bits,
         bits_read,
         <<s1::little-40, s2::little-32, rest::binary>>,
         carry,
         c
       )
       when remaining >= 4 do
    z1 = carry ||| s1 <<< c
    v = z1 &&& 0xFF
    e1_stat_id = v
    v = z1 >>> 8 &&& 0x3FF
    e1_delta = v - 512
    e1 = %Bench.MixedStat{stat_id: e1_stat_id, delta: e1_delta}
    v = z1 >>> 18 &&& 0xFF
    e2_stat_id = v
    v = z1 >>> 26 &&& 0x3FF
    e2_delta = v - 512
    e2 = %Bench.MixedStat{stat_id: e2_stat_id, delta: e2_delta}
    z2 = z1 >>> 36 ||| s2 <<< (c + 4)
    v = z2 &&& 0xFF
    e3_stat_id = v
    v = z2 >>> 8 &&& 0x3FF
    e3_delta = v - 512
    e3 = %Bench.MixedStat{stat_id: e3_stat_id, delta: e3_delta}
    v = z2 >>> 18 &&& 0xFF
    e4_stat_id = v
    v = z2 >>> 26 &&& 0x3FF
    e4_delta = v - 512
    e4 = %Bench.MixedStat{stat_id: e4_stat_id, delta: e4_delta}

    {bits_read, tail} =
      r_bench_mixed_stats_fast(
        remaining - 4,
        acc,
        data,
        num_bits,
        bits_read + 72,
        rest,
        z2 >>> 36,
        c
      )

    {bits_read, [e1, e2, e3, e4 | tail]}
  end

  defp r_bench_mixed_stats_fast(remaining, acc, data, num_bits, bits_read, _rest, _carry, _c),
    do: r_bench_mixed_stats(remaining, acc, data, num_bits, bits_read)

  defp r_bench_mixed_loadout(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_bench_mixed_loadout(remaining, acc, data, num_bits, bits_read)
       when remaining >= 4 do
    rv = rd(data, bits_read, 32)
    v = rv &&& 0xFF
    e1 = v
    v = rv >>> 8 &&& 0xFF
    e2 = v
    v = rv >>> 16 &&& 0xFF
    e3 = v
    v = rv >>> 24
    e4 = v
    r_bench_mixed_loadout(remaining - 4, [e4, e3, e2, e1 | acc], data, num_bits, bits_read + 32)
  end

  defp r_bench_mixed_loadout(remaining, acc, data, num_bits, bits_read) do
    rv = rd(data, bits_read, 8)
    v = rv
    e = v
    r_bench_mixed_loadout(remaining - 1, [e | acc], data, num_bits, bits_read + 8)
  end

  defp r_bench_mixed_loadout_align(remaining, acc, data, num_bits, bits_read)
       when remaining >= 4 do
    i = bits_read >>> 3
    q = bits_read &&& 7

    if q == 0 do
      case data do
        <<_::binary-size(^i), rest::binary>> ->
          r_bench_mixed_loadout_fast(remaining, acc, data, num_bits, bits_read, rest, 0, 0)

        _ ->
          r_bench_mixed_loadout(remaining, acc, data, num_bits, bits_read)
      end
    else
      case data do
        <<_::binary-size(^i), b0, rest::binary>> ->
          r_bench_mixed_loadout_fast(
            remaining,
            acc,
            data,
            num_bits,
            bits_read,
            rest,
            b0 >>> q,
            8 - q
          )

        _ ->
          r_bench_mixed_loadout(remaining, acc, data, num_bits, bits_read)
      end
    end
  end

  defp r_bench_mixed_loadout_align(remaining, acc, data, num_bits, bits_read),
    do: r_bench_mixed_loadout(remaining, acc, data, num_bits, bits_read)

  defp r_bench_mixed_loadout_fast(
         remaining,
         acc,
         data,
         num_bits,
         bits_read,
         <<s1::little-32, rest::binary>>,
         carry,
         c
       )
       when remaining >= 4 do
    z1 = carry ||| s1 <<< c
    v = z1 &&& 0xFF
    e1 = v
    v = z1 >>> 8 &&& 0xFF
    e2 = v
    v = z1 >>> 16 &&& 0xFF
    e3 = v
    v = z1 >>> 24 &&& 0xFF
    e4 = v

    {bits_read, tail} =
      r_bench_mixed_loadout_fast(
        remaining - 4,
        acc,
        data,
        num_bits,
        bits_read + 32,
        rest,
        z1 >>> 32,
        c
      )

    {bits_read, [e1, e2, e3, e4 | tail]}
  end

  defp r_bench_mixed_loadout_fast(remaining, acc, data, num_bits, bits_read, _rest, _carry, _c),
    do: r_bench_mixed_loadout(remaining, acc, data, num_bits, bits_read)
end
